// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout } from '@stdlib/types/blas';

/**
* Interface describing `dorgbr`.
*/
interface Routine {
	/**
	* Generates one of the real orthogonal matrices `Q` or `P^T` determined by `dgebrd` when reducing a real matrix `A` to bidiagonal form: `A = Q * B * P^T`.
	*
	* ## Notes
	*
	* -   `Q` and `P^T` are defined as products of elementary reflectors `H(i)` or `G(i)` respectively.
	* -   On exit, `A` is overwritten by the `M-by-N` matrix `Q` or `P^T`.
	* -   `WORK` must have length, `LWORK >= max(1,min(M,N))`. For optimum performance `LWORK >= min(M,N)*NB`, where `NB` is the optimal blocksize.
	* -   If `LWORK = -1`, then a workspace query is assumed.
	*
	* @param order - storage layout
	* @param vect - specifies whether the matrix `Q` or the matrix `P^T` is returned in `A`
	* @param M - number of rows of `Q` or `P^T`
	* @param N - number of columns of `Q` or `P^T`
	* @param K - number of elementary reflectors
	* @param A - input/output matrix
	* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
	* @param TAU - scalar factors of the elementary reflectors
	* @param WORK - workspace array
	* @param LWORK - dimension of the array `WORK`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1.0, 0.2, -0.1, 0.3, 0.0, 1.0, 0.4, -0.2, 0.0, 0.0, 1.0, 0.5 ] );
	* var TAU = new Float64Array( [ 1.3, 0.9, 1.1 ] );
	* var WORK = new Float64Array( 10 );
	*
	* dorgbr( 'column-major', 'Q', 4, 3, 3, A, 4, TAU, WORK, 10 );
	* // A => <Float64Array>[ -0.3, -0.26, 0.13, -0.39, -0.143, 0.0714, -0.3457, 0.1371, ~0.21, ~-0.021, ~-0.146, ~-0.474 ]
	* // WORK[ 0 ] => 96.0
	*/
	( order: Layout, vect: 'Q' | 'P', M: number, N: number, K: number, A: Float64Array, LDA: number, TAU: Float64Array, WORK: Float64Array, LWORK: number ): number;

	/**
	* Generates one of the real orthogonal matrices `Q` or `P^T` determined by `dgebrd` when reducing a real matrix `A` to bidiagonal form using alternative indexing semantics.
	*
	* ## Notes
	*
	* -   `Q` and `P^T` are defined as products of elementary reflectors `H(i)` or `G(i)` respectively.
	* -   On exit, `A` is overwritten by the `M-by-N` matrix `Q` or `P^T`.
	* -   `WORK` must have length, `LWORK >= max(1,min(M,N))`. For optimum performance `LWORK >= min(M,N)*NB`, where `NB` is the optimal blocksize.
	* -   If `LWORK = -1`, then a workspace query is assumed.
	*
	* @param vect - specifies whether the matrix `Q` or the matrix `P^T` is returned in `A`
	* @param M - number of rows of `Q` or `P^T`
	* @param N - number of columns of `Q` or `P^T`
	* @param K - number of elementary reflectors
	* @param A - input/output matrix
	* @param strideA1 - stride length for the first dimension of `A`
	* @param strideA2 - stride length for the second dimension of `A`
	* @param offsetA - starting index of `A`
	* @param TAU - scalar factors of the elementary reflectors
	* @param strideTAU - stride length for `TAU`
	* @param offsetTAU - starting index of `TAU`
	* @param WORK - workspace array
	* @param strideWORK - stride length for `WORK`
	* @param offsetWORK - starting index of `WORK`
	* @param LWORK - dimension of the array `WORK`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1.0, 0.2, -0.1, 0.3, 0.0, 1.0, 0.4, -0.2, 0.0, 0.0, 1.0, 0.5 ] );
	* var TAU = new Float64Array( [ 1.3, 0.9, 1.1 ] );
	* var WORK = new Float64Array( 10 );
	*
	* dorgbr.ndarray( 'Q', 4, 3, 3, A, 1, 4, 0, TAU, 1, 0, WORK, 1, 0, 10 );
	* // A => <Float64Array>[ -0.3, -0.26, 0.13, -0.39, -0.143, 0.0714, -0.3457, 0.1371, ~0.21, ~-0.021, ~-0.146, ~-0.474 ]
	* // WORK[ 0 ] => 96.0
	*/
	ndarray( vect: 'Q' | 'P', M: number, N: number, K: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, TAU: Float64Array, strideTAU: number, offsetTAU: number, WORK: Float64Array, strideWORK: number, offsetWORK: number, LWORK: number ): number;
}

/**
* LAPACK routine to generate one of the real orthogonal matrices `Q` or `P^T` determined by `dgebrd` when reducing a real matrix `A` to bidiagonal form: `A = Q * B * P^T`.
*
* ## Notes
*
* -   `Q` and `P^T` are defined as products of elementary reflectors `H(i)` or `G(i)` respectively.
* -   On exit, `A` is overwritten by the `M-by-N` matrix `Q` or `P^T`.
* -   `WORK` must have length, `LWORK >= max(1,min(M,N))`. For optimum performance `LWORK >= min(M,N)*NB`, where `NB` is the optimal blocksize.
* -   If `LWORK = -1`, then a workspace query is assumed.
*
* @param order - storage layout
* @param vect - specifies whether the matrix `Q` or the matrix `P^T` is returned in `A`
* @param M - number of rows of `Q` or `P^T`
* @param N - number of columns of `Q` or `P^T`
* @param K - number of elementary reflectors
* @param A - input/output matrix
* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param TAU - scalar factors of the elementary reflectors
* @param WORK - workspace array
* @param LWORK - dimension of the array `WORK`
* @returns status code
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 0.2, -0.1, 0.3, 0.0, 1.0, 0.4, -0.2, 0.0, 0.0, 1.0, 0.5 ] );
* var TAU = new Float64Array( [ 1.3, 0.9, 1.1 ] );
* var WORK = new Float64Array( 10 );
*
* dorgbr( 'column-major', 'Q', 4, 3, 3, A, 4, TAU, WORK, 10 );
* // A => <Float64Array>[ -0.3, -0.26, 0.13, -0.39, -0.143, 0.0714, -0.3457, 0.1371, ~0.21, ~-0.021, ~-0.146, ~-0.474 ]
* // WORK[ 0 ] => 96.0
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 0.2, -0.1, 0.3, 0.0, 1.0, 0.4, -0.2, 0.0, 0.0, 1.0, 0.5 ] );
* var TAU = new Float64Array( [ 1.3, 0.9, 1.1 ] );
* var WORK = new Float64Array( 10 );
*
* dorgbr.ndarray( 'Q', 4, 3, 3, A, 1, 4, 0, TAU, 1, 0, WORK, 1, 0, 10 );
* // A => <Float64Array>[ -0.3, -0.26, 0.13, -0.39, -0.143, 0.0714, -0.3457, 0.1371, ~0.21, ~-0.021, ~-0.146, ~-0.474 ]
* // WORK[ 0 ] => 96.0
*/
declare var dorgbr: Routine;


// EXPORTS //

export = dorgbr;
